const p = await browser.open('https://cha0smagicklabs.com/tools/tarot-journal.html');
await sleep(5000);
// aceptar cookies si aparece el banner
const consent = await p.evaluate(() => { try { const b = Array.from(document.querySelectorAll('button, a[role=button], [role=button]')).find(x => /accept(ar)?\s*cookies|aceptar|allow all|consent/i.test(String(x.innerText||x.getAttribute('aria-label')||''))); if (b) { b.click(); return String(b.innerText||'').trim().slice(0,40); } return null; } catch (e) { return null; } });
console.log('CONSENT ' + consent);
await sleep(4000);
const raw = await p.evaluate(() => { try {
  const res = performance.getEntriesByType('resource').map(r => r.name);
  const ga = res.filter(n => /google-analytics|googletagmanager|analytics\.google/.test(n));
  const events = [];
  for (const u of ga) { try { const q = new URL(u).searchParams; for (const k of ['en', 'ep', 'ev']) { const v = q.get(k); if (v) events.push(k + '=' + v); } } catch {} }
  return { total: res.length, gaCalls: ga.length, sample: ga.slice(0, 4).map(u => u.slice(0, 150)), events: events.slice(0, 25) };
} catch (e) { return { err: String(e.message).slice(0, 80) } } });
console.log('GA_CALLS ' + JSON.stringify((raw && 'value' in raw) ? raw.value : raw));
return 'ok';
